// src/components/DeviceList.jsx
import { useEffect, useState } from 'react';
import { ListBox } from 'primereact/listbox';
import { getDevices } from '../services/api';

export default function DeviceList({ selectedDevice, onSelect }) {
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    getDevices()
      .then((data) => {
        setDevices(data);
        // Якщо selectedDevice ще не вибрано — вибрати перший доступний
        if (!selectedDevice && data.length > 0) {
          onSelect(data[0]);
        }
      })
      .catch((err) => {
        console.error('Помилка завантаження пристроїв:', err);
        setError('Не вдалося завантажити список пристроїв.');
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  return (
    <div className="card">
      <h3>Пристрої</h3>

      {loading && <p>Завантаження пристроїв...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}

      {!loading && devices.length === 0 && (
        <p>Пристрої не знайдено.</p>
      )}

      {!loading && devices.length > 0 && (
        <ListBox
          value={selectedDevice}
          options={devices}
          onChange={(e) => onSelect(e.value)}
          optionLabel="name"
          className="w-full"
        />
      )}
    </div>
  );
}
